mapper.select:
SELECT latest.job_id, latest.start_time, latest.status FROM ( SELECT log.job_id, log.start_time, log.status, ROW_NUMBER() OVER ( PARTITION BY log.job_id ORDER BY log.create_time DESC, log.id DESC ) AS row_num FROM ops_job_log log WHERE log.is_deleted = 0 AND log.job_id IN
#{jobId}
) latest WHERE latest.row_num = 1
